    if ($extraClass !== '') {
        $classAttr .= ' ' . htmlspecialchars($extraClass, ENT_QUOTES, 'UTF-8');
    }

    $styleAttr = '';
    if ($extraStyle !== '') {
        $styleAttr = ' style="' . htmlspecialchars($extraStyle, ENT_QUOTES, 'UTF-8') . '"';
    }

    return sprintf(
